    grams = int(grams)
    if grams >= 1000:
        kilograms = 0
        kilograms = grams / 1000.0
        # If there is no remainder, convert the float to an integer
        # so that the '.0' is removed.
        if not (grams % 1000):
            kilograms = int(kilograms)
        return u'%s %s' % (str(kilograms), 'kg')
    else:
        return u'%s %s' % (str(grams), 'g')

